//★Wcraft guide★ include부분 주석처리 -> include("../js/libRoundPanel.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/stf.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/utils.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/session.js");
//★Wcraft guide★ include부분 주석처리 -> include("../js/PopupCalendar.js");
scwin.gDepCd = js_dep_cd;
scwin.gEmpNo = js_emp_no;
scwin.gLdMktTp = js_market;
scwin.gUsrTpCd = js_usr_tp_cd;
scwin.gLastJob = "";
scwin.strCBData;
scwin.vScrenID = "ULDSTF30403.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};
scwin.initPage = function() {
    if (frame.FrameID == "INTEBBS_NEW") {
        // gfm은 정적인 화면이라 변수값을 받을 수 없어. 창의 이름으로 신규와 수정을 구별한다.
        scwin.fn_SetNewMode();
        $c.stf.setObjectValue(txb_WRTR_EMP_NO, scwin.gEmpNo);
        $c.stf.setObjectValue(txb_WRTR_EMP_NM, js_emp_nm);
        $c.stf.setObjectValue(txb_LD_MKT_TP_CD, scwin.gLdMktTp);
        cmb_MENU_FLAG.setSelectedIndex(0);
        $c.stf.setObjectValue(chk_OBJ_SYSTEM1, "N");
        $c.stf.setObjectValue(chk_OBJ_SYSTEM2, "N");
        $c.stf.setObjectValue(chk_OBJ_SYSTEM3, "N");
        $c.stf.setObjectValue(chk_OBJ_SYSTEM4, "N");
        $c.stf.setObjectValue(chk_OBJ_SYSTEM5, "N");
        $c.stf.showObj(btn_Delete, false);
    } else {
        scwin.fn_SetEditMode();
    }
};
scwin.fn_SetNewMode = function() {
    dts_MASTER.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INTEBBS_LIST";
    dts_MASTER.Reset();
    dts_MASTER.insertRow();
    dts_FILE_LIST.DataID = "/gauceSystemierAdaptor.do?method=getGauceDataHeader&messageId=INTEBBS_LIST_ATTACH";
    dts_FILE_LIST.Reset();
    //	dts_MASTER.AddRow();	
    //	dts_FILE_LIST.SetDataHeader("fileInfo:String,fileUrl:URL");

};
scwin.fn_SetEditMode = function() {
    //"INTEBBS_READ|CONTN_ID=" + CONTN_ID
    var vTemp = frame.FrameID;
    var Temp2 = vTemp.split("|")[1];
    var vCONTN_ID = Temp2.split("=")[1];
    //alert(vCONTN_ID);
    var url = "/IntegratedBBS.do?method=readDsclBbs";
    url += "&CONTN_ID=" + vCONTN_ID;
    //alert(url);
    dts_MASTER.DataID = encodeURI(url);
    dts_MASTER.Reset();
    url = "/IntegratedBBS.do?method=listInteBBSAttach";
    url += "&CONTN_ID=" + vCONTN_ID;
    dts_FILE_LIST.DataID = encodeURI(url);
    dts_FILE_LIST.Reset();
};
scwin.fn_SetCode = function() {

};
scwin.fn_HideDebugCtrls = function() {
    $c.stf.showObj(panel_debug, false);
};
scwin.fn_CheckForm = function() {
    if ($c.stf.getObjectValue(txb_WRTR_EMP_NM) == "") {
        $c.win.alert("[등록자]를 입력하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_WRTR_EMP_NM).length > 10) {
        $c.win.alert("[등록자]명을 10자 이내로 입력해 주세요.");
        txb_WRTR_EMP_NM.focus();
        return false;
    }
    if ($c.stf.getObjectValue(chk_OBJ_SYSTEM1) == "N" &&
        $c.stf.getObjectValue(chk_OBJ_SYSTEM2) == "N" &&
        $c.stf.getObjectValue(chk_OBJ_SYSTEM3) == "N" &&
        $c.stf.getObjectValue(chk_OBJ_SYSTEM4) == "N" &&
        $c.stf.getObjectValue(chk_OBJ_SYSTEM5) == "N") {
        $c.win.alert("[공지대상시스템]를 선택하세요.");
        return false;
    }
    if ($c.stf.getObjectValue(txb_WRTR_EMAIL) == "") {
        $c.win.alert("[이메일]를 입력하세요.");
        txb_WRTR_EMAIL.focus();
        return false;
    }
    if ($c.stf.IsValidEmail($c.stf.getObjectValue(txb_WRTR_EMAIL)) == false) {
        $c.win.alert("[이메일] 정확하지 않습니다.");
        txb_WRTR_EMAIL.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_PW) == "") {
        $c.win.alert("[비밀번호]를 입력하세요.");
        txb_PW.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_TITLE) == "") {
        $c.win.alert("[제목]를 입력하세요.");
        txb_TITLE.focus();
        return false;
    }
    if ($c.stf.getObjectValue(cmb_MENU_FLAG) == "" && chk_OBJ_SYSTEM4.checked != true) {
        $c.win.alert("[메뉴구분]를 선택하세요.");
        cmb_MENU_FLAG.focus();
        return false;
    }
    if ($c.stf.getObjectValue(rdo_mkt_gubun) == "") {
        $c.win.alert("[시장구분]를 선택하세요.");
        rdo_mkt_gubun.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txa_CONTN_CONTN) == "") {
        $c.win.alert("[내용]를 입력하세요.");
        txa_CONTN_CONTN.focus();
        return false;
    }
    if ($c.stf.getObjectValue(txb_CONTN_ID) == "") {
        //alert("[비밀번호]를 입력하세요.");txb_CONTN_ID.focus();return false;

    }
    if ($c.stf.getObjectValue(txb_WRTR_EMP_NO) == "") {
        //alert("[비밀번호]를 입력하세요.");txb_WRTR_EMP_NO.focus();return false;

    }
    if ($c.stf.getObjectValue(cmb_MENU_FLAG) == "31" || $c.stf.getObjectValue(cmb_MENU_FLAG) == "32") {
        if ($c.stf.getObjectValue(cmb_MENU_FLAG) == "31" && ($c.stf.getObjectValue(chk_OBJ_SYSTEM1) == "N" || ($c.stf.getObjectValue(chk_OBJ_SYSTEM1) == "Y" && $c.stf.getObjectValue(chk_OBJ_SYSTEM2) == "Y"))) {
            $c.win.alert("[공시체크포인트]는 제출시스템에만 적용됩니다.\n공지대상시스템을 [제출]로 선택하여주세요.");
            return false;
        }
        if ($c.stf.getObjectValue(cmb_MENU_FLAG) == "32" && ($c.stf.getObjectValue(chk_OBJ_SYSTEM1) == "N" || ($c.stf.getObjectValue(chk_OBJ_SYSTEM1) == "Y" && $c.stf.getObjectValue(chk_OBJ_SYSTEM2) == "Y"))) {
            $c.win.alert("[업무사례]는 제출시스템에만 적용됩니다.\n공지대상시스템을 [제출]로 선택하여주세요.");
            return false;
        }
        if ($c.stf.getObjectValue(cmb_MENU_FLAG) == "31" && $c.stf.getObjectValue(rdo_mkt_gubun) == "4") {
            $c.win.alert("[공시체크포인트]은 시장구분[채권]에 적용할 수 없습니다.");
            return false;
        }
        if ($c.stf.getObjectValue(cmb_MENU_FLAG) == "32" && $c.stf.getObjectValue(rdo_mkt_gubun) == "4") {
            $c.win.alert("[업무사례]는 시장구분[채권]에 적용할 수 없습니다.");
            return false;
        }
        //alert("[비밀번호]를 입력하세요.");txb_WRTR_EMP_NO.focus();return false;

    }
    //202405 밸류업 추가 
    if ($c.stf.getObjectValue(cmb_MENU_FLAG) == "62") {
        if ($c.stf.getObjectValue(chk_OBJ_SYSTEM2) == "Y" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM1) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM3) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM4) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM5) == "N") {

        } else {
            $c.win.alert("[밸류업 자료실(국문)]은 조회(국문)시스템만 적용됩니다. \n공지대상시스템을 [조회(국문)]만 선택하여주세요.");
            return false;
        }
    }
    if ($c.stf.getObjectValue(cmb_MENU_FLAG) == "63") {
        if ($c.stf.getObjectValue(chk_OBJ_SYSTEM2) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM1) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM3) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM4) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM5) == "Y") {

        } else {
            $c.win.alert("[밸류업 자료실(영문)]은 조회(영문)시스템만 적용됩니다. \n공지대상시스템을 [조회(영문)]만 선택하여주세요.");
            return false;
        }
    }
    if ($c.stf.getObjectValue(chk_OBJ_SYSTEM4) == "Y") {
        //K-CLIC 
        if ($c.stf.getObjectValue(cmb_sprt_room_grp) == "") {
            $c.win.alert("공지대상시스템이 K-CLIC인 경우에는 게시물유형을 선택해 주세요.");
            cmb_sprt_room_grp.focus();
            return false;
        }
        if ($c.stf.getObjectValue(cmb_chrg_inst_id) == "") {
            $c.win.alert("공지대상시스템이 K-CLIC인 경우에는 담당기관을 선택해 주세요.");
            cmb_chrg_inst_id.focus();
            return false;
        }
        /*
        if(getObjectValue(cmb_MENU_FLAG) != "02"){
        	alert("공지대상시스템이 K-CLIC인 경우에는 메뉴구분은 자료실만 선택가능합니다.");
        	cmb_MENU_FLAG.Focus();
        	return false;
        }*/
    }

    //날짜확인
    if (!$c.stf.compareFromToDate2(edt_SDate, edt_EDate)) {
        edt_SDate.focus();
        return false;
    }
    return true;
};
scwin.fn_Save = function() {
    if (scwin.fn_CheckForm() == false) return;
    //	alert(dts_MASTER.namestring(1, "OBJ_SYSTEM1"));
    //	alert(dts_MASTER.namestring(1, "OBJ_SYSTEM2"));
    //	return;
    var res = window.confirm("[저장]하시겠습니까?");
    if (res) {
        scwin.gLastJob = "저장";
        var url = "/IntegratedBBS.do?method=registerDsclBbs" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_02;
        //alert(dts_MASTER.Text);
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER, I:pFile=dts_FILE_LIST)";
        trs_Save.post();
    }
};
scwin.fn_Delete = function() {
    var vPW = $c.stf.getObjectValue(txb_PW);
    if (vPW == "") {
        $c.win.alert("[비밀번호]를 입력하세요.");
        txb_PW.focus();
        return;
    }
    var res = window.confirm("[삭제]하시겠습니까?");
    if (res) {
        scwin.gLastJob = "삭제";
        var url = "/IntegratedBBS.do?method=removeDsclBbs" + "&SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_04;
        //alert(dts_MASTER.Text);
        trs_Save.Action = url;
        trs_Save.KeyName = "toinb_dataid4";
        trs_Save.KeyValue = "JSP(I:pInputMaster=dts_MASTER)";
        trs_Save.post();
    }
};
scwin.fn_DownLoad = function(row, colid) {
    var filename = dts_FILE_LIST.getCellData(row, "ATTACH_FILE_NM");
    if (filename == "") return;
    if (colid == "ATTACH_FILE_NM") {
        var vCONTN_ID = dts_FILE_LIST.getCellData(row, "CONTN_ID");
        var vCONTN_ATTACH_SEQ = dts_FILE_LIST.getCellData(row, "CONTN_ATTACH_SEQ");
        location.href = "/filedownload.do?file_id=" + vCONTN_ID + "&attach_seq=" + vCONTN_ATTACH_SEQ + "&gubun=2";
    }
};
scwin.fn_setKclicStatus = function(status) {
    if (chk_OBJ_SYSTEM4.checked == true) {
        cmb_sprt_room_grp.setDisabled(false);
        cmb_chrg_inst_id.setDisabled(false);
        if (chk_OBJ_SYSTEM2.checked == false && chk_OBJ_SYSTEM1.checked == false) {
            if ('init' != status) {
                $c.stf.setObjectValue(cmb_MENU_FLAG, '02');
            }
            cmb_MENU_FLAG.setDisabled(true);
        }
    } else if (chk_OBJ_SYSTEM5.checked == true) {
        scwin.strCBData = "^선택하세요,04^공시발간자료,02^자료실,31^공시체크포인트,32^업무사례,62^밸류업자료실(국문),63^밸류업자료실(영문)";
        cmb_MENU_FLAG.CBData = scwin.strCBData;
        $c.stf.setObjectValue(cmb_MENU_FLAG, '63');
        cmb_MENU_FLAG.setDisabled(true);
        $c.stf.setObjectValue(rdo_mkt_gubun, '9');
        rdo_mkt_gubun.setDisabled(true);
        cmb_sprt_room_grp.setDisabled(true);
        cmb_chrg_inst_id.setDisabled(true);
        $c.stf.setObjectValue(cmb_sprt_room_grp, '');
        $c.stf.setObjectValue(cmb_chrg_inst_id, '');
        chk_OBJ_SYSTEM4.setValue(0);
        chk_OBJ_SYSTEM4.setDisabled(true);
        chk_OBJ_SYSTEM3.setValue(0);
        chk_OBJ_SYSTEM3.setDisabled(true);
        chk_OBJ_SYSTEM2.setValue(0);
        chk_OBJ_SYSTEM2.setDisabled(true);
        chk_OBJ_SYSTEM1.setValue(0);
        chk_OBJ_SYSTEM1.setDisabled(true);
    } else {
        cmb_sprt_room_grp.setDisabled(true);
        cmb_chrg_inst_id.setDisabled(true);
        $c.stf.setObjectValue(cmb_sprt_room_grp, '');
        $c.stf.setObjectValue(cmb_chrg_inst_id, '');
        cmb_MENU_FLAG.setDisabled(false);
    }
    if (chk_OBJ_SYSTEM5.checked == false && chk_OBJ_SYSTEM4.checked == false && chk_OBJ_SYSTEM2.checked == false && chk_OBJ_SYSTEM1.checked == false) {
        cmb_sprt_room_grp.setDisabled(false);
        cmb_chrg_inst_id.setDisabled(false);
        cmb_MENU_FLAG.setDisabled(false);
        rdo_mkt_gubun.setDisabled(false);
    }
};


//2017-02-13 KBoY FileSizeLimit 30MB		
scwin.canUploadFile = function(size) {
    var maxFileSize = 1024 * 1024 * 30; //30MB		
    if (size < maxFileSize) {
        return true;
    } else {
        return false;
    }
};



//20250718 파일 확장자 체크로직 추가
scwin.fn_CheckExtension = function(fileNm) {
    var fileExts = new Array(".hwp", ".docx", ".doc", ".xls", ".xlsx", ".ppt", ".pptx", ".pdf", ".gif", ".jpg", ".jpeg", ".bmp", ".tif", ".txt", ".drt", ".dsd", ".png", ".zip"); // 허가 확장자 목록
    var vsFileNm = fileNm;
    var vsFileExts = vsFileNm.substr(vsFileNm.lastIndexOf("."), vsFileNm.length);
    var vsFlag = true;
    var ext = fileNm.substr(fileNm.lastIndexOf(".")).toLowerCase();
    for (var i = 0; i < fileExts.length; i++) {
        if (fileExts[i] == vsFileExts || fileExts[i] == ext) {
            vsFlag = false;
            break;
        }
    }
    if (vsFlag) {
        $c.win.alert("업로드할 수 없는 확장자입니다. 확인바랍니다.");
        return true;
    }
    return false;
};


//20250718
scwin.showAlertMsg = function(msg) {
    if (msg.indexOf('50014') != -1) {
        $c.win.alert('첨부하려는 파일을 열어놓은 경우, 파일 첨부가 불가능 합니다.\r\n첨부하려는 파일을 닫고 다시 진행하시기 바랍니다.');
    } else {
        $c.win.alert(msg);
    }
};
scwin.checkMaxLength1 = function(filestr, size, lbl) {
    var overLen = eval($c.stf.getStringSize(filestr) - size);
    if (overLen > 0) {
        $c.win.alert("[ " + lbl + " ] 의 최대길이는 [ " + size + " ] byte 입니다.    \n\n[ " + overLen + " ] byte 를 초과하였습니다.\n\n확인하세요. ( 한글 : 2 byte  숫자,영문 : 1 byte )");
        return true;
    }
    return false;
};
scwin.btn_AddRow_onclick = function() {
    // 공시발간자료 일 경우에만 파일첨부 6개까지 허용 가능토록 수정 by LDJ_20130219
    if ($c.stf.getObjectValue(cmb_MENU_FLAG) == "04") {
        if (dts_FILE_LIST.getTotalRow() == 6) {
            $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
    } else {
        if (dts_FILE_LIST.getTotalRow() == 5) {
            $c.win.alert("더이상 추가하실 수 없습니다.");
            return;
        }
    }
    btn_File.open();

    //파일 확장자 체크 추가
    var vFile = btn_File.getValue();
    var vFileNm = vFile.split("\\");
    vFileNm = vFileNm[vFileNm.length - 1];
    if (vFileNm != "") {
        if (scwin.checkMaxLength1(vFileNm, '80', "파일명")) return; //파일명 80자 체크
        if (scwin.fn_CheckExtension(vFileNm)) return; // 파일 확장자 체크
        dts_FILE_LIST.insertRow();
    } else {
        return;
    }
    if (!scwin.canUploadFile(btn_File.FileInfo('size'))) {
        $c.win.alert('30MB 이하의 파일만 첨부 가능합니다.');
        $c.cp.removeRow(dts_FILE_LIST, dts_FILE_LIST.getRowPosition());
        return;
    } else {
        if (btn_File.getValue() != "") {
            dts_FILE_LIST.setCellData(dts_FILE_LIST.getRowPosition(), "ATTACH_FILE_NM", btn_File.getValue());
            dts_FILE_LIST.setCellData(dts_FILE_LIST.getRowPosition(), "FILEURL", btn_File.getValue());
        } else {
            $c.cp.removeRow(dts_FILE_LIST, dts_FILE_LIST.getRowPosition());
        }
    }
    btn_File.setValue("");
};
scwin.btn_DelRow_onclick = function() {
    $c.cp.removeRow(dts_FILE_LIST, dts_FILE_LIST.getRowPosition());
};
scwin.btn_Save_onclick = function() {
    scwin.fn_Save();
};
scwin.btn_Delete_onclick = function() {
    scwin.fn_Delete();
};
scwin.btn_Cancel_onclick = async function() {
    await $c.frame.CloseFrame();
};
scwin.trs_Save_OnFail = function() {
    scwin.showAlertMsg(trs_Save.ErrorMsg); //20250718

};
scwin.trs_Save_OnSuccess = async function() {
    var msg = $c.stf.getMessageParam("MSG-A001", scwin.gLastJob);
    $c.win.alert(msg);
    var fr_fn_Search = $c.frame.path("../").fn_listDsclBbs;
    fr_fn_Search();
    await $c.frame.CloseFrame();
};
scwin.grd_FILE_LIST_OnClick = function(row, colid) {
    scwin.fn_DownLoad(row, colid);
};
scwin.gform_onload = function() {
    // 영문공시제출 오픈시 아래 부분 삭제
    //--------------------------------------------------
    $c.stf.showObj(label_28, false);
    $c.stf.showObj(pnl_eng_fil, false);
    //----------------------------------------------------

    $c.libRoundPanel.PanelToGroupBox(panel_1);
    scwin.fn_HideDebugCtrls();
    scwin.strCBData = "^선택하세요,04^공시발간자료,02^자료실,31^공시체크포인트,32^업무사례,62^밸류업자료실(국문)";
    cmb_MENU_FLAG.CBData = scwin.strCBData;
    $c.stf.setObjectValue(cmb_MENU_FLAG, '');
    scwin.fn_SetCode();
    scwin.initPage();
    scwin.fn_setKclicStatus('init');
};
scwin.icn_SCal_onclick = function() {
    popUpCalendar2(edt_SDate);
};
scwin.icn_ECal_onclick = function() {
    popUpCalendar2(edt_EDate);
};
scwin.cmb_MENU_FLAG_OnSelChange = function() {
    var gValueUp = $c.cp.valueOfIndex(cmb_MENU_FLAG, "VALUE", cmb_MENU_FLAG.getSelectedIndex());
    if (gValueUp == '62') {
        //밸류업자료실(국문)
        $c.stf.setObjectValue(rdo_mkt_gubun, '9');
        rdo_mkt_gubun.setDisabled(true);
        if ($c.stf.getObjectValue(chk_OBJ_SYSTEM2) == "Y" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM1) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM3) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM4) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM5) == "N") {

        } else {
            $c.win.alert("[밸류업 자료실(국문)]은 조회(국문)시스템만 적용됩니다. \n공지대상시스템을 [조회(국문)]만 선택해주세요.");
        }
    } else if (gValueUp == '63') {
        //밸류업자료실(영문)
        if ($c.stf.getObjectValue(chk_OBJ_SYSTEM2) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM1) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM3) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM4) == "N" &&
            $c.stf.getObjectValue(chk_OBJ_SYSTEM5) == "Y") {

        } else {
            $c.win.alert("[밸류업 자료실(영문)]은 조회(영문)시스템만 적용됩니다. \n공지대상시스템을 [조회(영문)]만 선택해주세요.");
        }
    } else {
        rdo_mkt_gubun.setDisabled(false);
    }
};
