scwin.chk_OBJ_SYSTEM1_onclick = function() {
    //제출(국문)
    if (chk_OBJ_SYSTEM1.checked == true) {
        cmb_MENU_FLAG.setDisabled(false);
        if (chk_OBJ_SYSTEM4.checked == false) {
            cmb_sprt_room_grp.setDisabled(true);
            cmb_chrg_inst_id.setDisabled(true);
            $c.stf.setObjectValue(cmb_sprt_room_grp, '');
            $c.stf.setObjectValue(cmb_chrg_inst_id, '');
        }
    }
    if (chk_OBJ_SYSTEM5.checked == false && chk_OBJ_SYSTEM4.checked == false && chk_OBJ_SYSTEM2.checked == false && chk_OBJ_SYSTEM1.checked == false) {
        cmb_sprt_room_grp.setDisabled(false);
        cmb_chrg_inst_id.setDisabled(false);
        cmb_MENU_FLAG.setDisabled(false);
        rdo_mkt_gubun.setDisabled(false);
    }
    scwin.fn_setKclicStatus();
};
